      case 3:
        g_pD3DDevice->lpVtbl->SetRenderState(g_pD3DDevice, 0x1b, 1);
        g_pD3DDevice->lpVtbl->SetRenderState(g_pD3DDevice, 0x13, 1);
        g_pD3DDevice->lpVtbl->SetRenderState(g_pD3DDevice, 0x14, 3);
        break;
      case 4:
        g_pD3DDevice->lpVtbl->SetRenderState(g_pD3DDevice, 0x1b, 1);
